package semver

import "fmt"

func lokiCases() {
	lokiCase("c1", "change", "NewConstraint * with 1.2.3", func() any {
		c, _ := NewConstraint("*")
		v, _ := NewVersion("1.2.3")
		return c.Check(v)
	})
	lokiCase("c2", "change", "NewConstraint * with 0.0.1", func() any {
		c, _ := NewConstraint("*")
		v, _ := NewVersion("0.0.1")
		return c.Check(v)
	})
	lokiCase("c3", "change", "constraintTilde directly on parsed * with 1.2.3", func() any {
		c, _ := parseConstraint("*")
		v, _ := NewVersion("1.2.3")
		return constraintTilde(v, c)
	})

	lokiCase("k1", "keep", "NewConstraint ~1.2.3 with 1.2.4", func() any {
		c, _ := NewConstraint("~1.2.3")
		v, _ := NewVersion("1.2.4")
		return c.Check(v)
	})
	lokiCase("k2", "keep", "NewConstraint ~1.2.3 with 1.3.0", func() any {
		c, _ := NewConstraint("~1.2.3")
		v, _ := NewVersion("1.3.0")
		return c.Check(v)
	})
	lokiCase("k3", "keep", "NewConstraint ~1.2.3 with 1.2.2", func() any {
		c, _ := NewConstraint("~1.2.3")
		v, _ := NewVersion("1.2.2")
		return c.Check(v)
	})
	lokiCase("k4", "keep", "NewConstraint ~1.2.3 with 2.0.0", func() any {
		c, _ := NewConstraint("~1.2.3")
		v, _ := NewVersion("2.0.0")
		return c.Check(v)
	})
	lokiCase("k5", "keep", "NewConstraint ^1.2.3 with 1.9.0", func() any {
		c, _ := NewConstraint("^1.2.3")
		v, _ := NewVersion("1.9.0")
		return c.Check(v)
	})
	lokiCase("k6", "keep", "NewConstraint 1.2.3 with 1.2.3", func() any {
		c, _ := NewConstraint("1.2.3")
		v, _ := NewVersion("1.2.3")
		return c.Check(v)
	})
	lokiCase("k7", "keep", "NewConstraint !=1.2.3 with 1.2.4", func() any {
		c, _ := NewConstraint("!=1.2.3")
		v, _ := NewVersion("1.2.4")
		return c.Check(v)
	})
	lokiCase("k8", "keep", "NewConstraint 1.x with 1.5.0", func() any {
		c, _ := NewConstraint("1.x")
		v, _ := NewVersion("1.5.0")
		return c.Check(v)
	})
	lokiCase("k9", "keep", "NewConstraint padded ~> 1.2 with 1.2.9", func() any {
		c, _ := NewConstraint("  ~>1.2  ")
		v, _ := NewVersion("1.2.9")
		return c.Check(v)
	})
	lokiCase("k10", "keep", "NewConstraint 1.2.3 || 2.x with 2.5.0", func() any {
		c, _ := NewConstraint("1.2.3 || 2.x")
		v, _ := NewVersion("2.5.0")
		return c.Check(v)
	})
	lokiCase("k11", "keep", "parseConstraint foo error", func() any {
		_, err := parseConstraint("foo")
		return fmt.Sprint(err)
	})
	lokiCase("k12", "keep", "parseConstraint 1.0 con string and dirty flag", func() any {
		c, _ := parseConstraint("1.0")
		return lokiAll(c.con.String(), c.dirty)
	})
}

package humanize

import (
	"fmt"
	"math"
)

func lokiCases() {
	lokiCase("c1", "change", "SI(+Inf, x)", func() any {
		return SI(math.Inf(1), "x")
	})
	lokiCase("c2", "change", "SI(-Inf, x)", func() any {
		return SI(math.Inf(-1), "x")
	})
	lokiCase("c3", "change", "ComputeSI(+Inf) value and prefix", func() any {
		return lokiAll(ComputeSI(math.Inf(1)))
	})

	lokiCase("k1", "keep", "SI(0, F)", func() any {
		return SI(0, "F")
	})
	lokiCase("k2", "keep", "SI(1e-30, F) lowest prefix", func() any {
		return SI(1e-30, "F")
	})
	lokiCase("k3", "keep", "SI(1e31, F) above table clamp", func() any {
		return SI(1e31, "F")
	})
	lokiCase("k4", "keep", "SI(1e-31, F) below table clamp", func() any {
		return SI(1e-31, "F")
	})
	lokiCase("k5", "keep", "SI(NaN, x)", func() any {
		return SI(math.NaN(), "x")
	})
	lokiCase("k6", "keep", "SI(-2.2e-12, F) negative", func() any {
		return SI(-2.2e-12, "F")
	})
	lokiCase("k7", "keep", "SIWithDigits(1e6, 0, B)", func() any {
		return SIWithDigits(1e6, 0, "B")
	})
	lokiCase("k8", "keep", "SIWithDigits(2.234e-12, 2, F)", func() any {
		return SIWithDigits(2.234e-12, 2, "F")
	})
	lokiCase("k9", "keep", "ParseSI of 2.2345 pF", func() any {
		v, u, err := ParseSI("2.2345 pF")
		return lokiAll(v, u, fmt.Sprint(err))
	})
	lokiCase("k10", "keep", "ParseSI of x1.21JW error", func() any {
		_, _, err := ParseSI("x1.21JW")
		return fmt.Sprint(err)
	})
	lokiCase("k11", "keep", "Ftoa(+Inf)", func() any {
		return Ftoa(math.Inf(1))
	})
	lokiCase("k12", "keep", "ComputeSI(0)", func() any {
		return lokiAll(ComputeSI(0))
	})
}

